using Microsoft.EntityFrameworkCore;

// Cosmos DB project context — fixes for EF Core 9 Cosmos breaking changes
class CosmosDbContext : DbContext
{
    public DbSet<Session> Sessions => Set<Session>();

    protected override void OnConfiguring(DbContextOptionsBuilder options)
        => options.UseCosmos("AccountEndpoint=https://localhost:8081/;AccountKey=key", "MyDb");

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // Fix: Cosmos DB discriminator property renamed from "Discriminator" to "$type" in EF Core 9.
        // Existing documents use "Discriminator", so explicitly configure it to preserve compatibility.
        modelBuilder.Entity<Session>().HasDiscriminator<string>("Discriminator");

        // Fix: id property no longer contains the discriminator value in EF Core 9.
        // Existing documents have compound ids like "Session|abc123".
        // Preserve the old format so existing documents remain accessible.
        modelBuilder.Entity<Session>().HasRootDiscriminatorInJsonId(true);
    }
}

class Session
{
    public string Id { get; set; } = "";
    public string Name { get; set; } = "";
}

// Fix: Sync I/O (ToList, SaveChanges, etc.) no longer supported on Cosmos DB provider in EF Core 9.
// All queries must use async equivalents.
class CosmosService
{
    private readonly CosmosDbContext _db;

    public CosmosService(CosmosDbContext db) => _db = db;

    // BEFORE (throws in EF Core 9):
    //   var sessions = _db.Sessions.ToList();
    //   _db.SaveChanges();

    // AFTER — use async methods:
    public async Task<List<Session>> GetSessionsAsync()
        => await _db.Sessions.ToListAsync();

    public async Task AddSessionAsync(Session session)
    {
        _db.Sessions.Add(session);
        await _db.SaveChangesAsync();
    }
}

